Few weeks ago I was asking how to calculate the skewness of experimental
data.

Thanks to Richard Pugh who gave me the predefined functions of kurtosis and
skewness of Splus6.

Here below I report the two functions, they might be useful for people (like
me) who do not have the updated versions of Splus.
thank you again
Stefano

kurtosis <- function(x, na.rm = F, method = "fisher")
{
method <- char.expand(method, c("fisher", "moment"), stop("argument 'method'
must match either \"fisher\" or \"moment\""))
if(na.rm) {
wnas <- which.na(x) 
if(length(wnas)) 
x <- x[ - wnas]
}
else if(length(which.na(x))) 
return(NA)
n <- as.double(length(x)) 
if(method == "fisher" && n < 4)
return(NA)
x <- x - mean(x)
if(method == "moment") 
(sum(x^4)/n)/(sum(x^2)/n)^2 - 3
else 
((n + 1) * (n - 1) * ((sum(x^4)/n)/(sum(x^2)/n)^2 - (3 * (n - 1 ))/(n +
1)))/((n - 2) * (n - 3))
}

skewness <- function(x, na.rm = F, method = "fisher")
{
method <- char.expand(method, c("fisher", "moment"), stop("argument 'method'
must match either \"fisher\" or \"moment\""))
if(na.rm) {
wnas <- which.na(x) 
if(length(wnas)) 
x <- x[ - wnas]
}
else if(length(which.na(x))) 
return(NA)
n <- as.double(length(x)) 
if(method == "fisher" && n < 3)
return(NA)
x <- x - mean(x)
if(method == "moment") 
(sum(x^3)/n)/(sum(x^2)/n)^1.5
else 
((sqrt(n * (n - 1))/(n - 2)) * (sum(x^3)/n))/((sum(x^2)/n)^1.5)
}

